INSERT INTO governor_actions (id, bill_number, session, title, raw_status, action, action_key, action_label, action_date, chapter_number, effective_date, governor, sponsor_name, sponsor_party, source_url, fetched_at, sponsor_lis_id) VALUES (2061, 'HB1426', '2026', 'Judgments; limitations on enforcement, docketing of gen. district court judgments in circuit court.', 'Approved by Governor-Chapter 848 (effective 7/1/2026)', 'signed', 'signed', 'Signed into law', '2026-04-13', '848', '7/1/2026', 'Spanberger', 'Marcus B. Simon', '', 'https://openstates.org/va/bills/2026/HB1426/', '2026-05-24 03:48:33', NULL);
INSERT INTO governor_actions (id, bill_number, session, title, raw_status, action, action_key, action_label, action_date, chapter_number, effective_date, governor, sponsor_name, sponsor_party, source_url, fetched_at, sponsor_lis_id) VALUES (4139, 'HB642', '2026', 'Cannabis control; establishes framework for creation of retail marijuana market, penalties, report.', 'Vetoed by Governor; previous status: Substitute bill reprinted 26110214D', 'vetoed', 'vetoed', 'Vetoed', '2026-05-19', '', '', 'Spanberger', '', '', 'https://www.governor.virginia.gov/newsroom/news-releases/2026/may-releases/name-1118109-en.html', '2026-05-24 03:48:34', NULL);
INSERT INTO governor_actions (id, bill_number, session, title, raw_status, action, action_key, action_label, action_date, chapter_number, effective_date, governor, sponsor_name, sponsor_party, source_url, fetched_at, sponsor_lis_id) VALUES (4140, 'SB542', '2026', 'Cannabis control; establishes framework for creation of retail marijuana market, penalties, report.', 'Vetoed by Governor; previous status: Substitute bill reprinted 26110453D', 'vetoed', 'vetoed', 'Vetoed', '2026-05-19', '', '', 'Spanberger', '', '', 'https://www.governor.virginia.gov/newsroom/news-releases/2026/may-releases/name-1118109-en.html', '2026-05-24 03:48:34', NULL);
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (1, '16 (2026)', 'A SAFER VIRGINIA FOR ALL', '2026-05-20', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order outlines the Commonwealth of Virginia''s policy regarding federal civil immigration enforcement to protect residents and guide state and local public servants. It responds to a significant increase in immigration-related detentions, including those of individuals not convicted of crimes and children, aiming to mitigate the impact of aggressive federal tactics while ensuring adherence to constitutional principles and maintaining public trust in law enforcement. The order mandates various state agencies to develop specific guidance and resources for interacting with federal immigration officers in public and non-public settings such as schools, courthouses, and polling places.', '["Immigration Enforcement", "Civil Liberties", "State-Federal Relations", "Law Enforcement Policy", "Public Safety", "Education", "Healthcare", "Legal Guidance", "Community Trust"]', '["Executive Branch Departments and Agencies", "Department of Criminal Justice Services", "Commonwealth''s Attorneys'' Services Council", "Department of Elections", "Virginia Department of Education", "State Council of Higher Education for Virginia", "Virginia Community College System", "Virginia Department of Health", "Secretary of Administration", "Secretary of Public Safety and Homeland Security"]', '["Confirm federal immigration officers possess valid warrants or orders for entering, accessing, or using nonpublic areas of Commonwealth property.", "Prohibit federal immigration officers from using nonpublic areas of Commonwealth property as a staging, processing, or operations base for civil immigration enforcement.", "Department of Criminal Justice Services to develop guidance for courthouse and courtroom security regarding federal civil immigration arrests.", "Commonwealth''s Attorneys'' Services Council to develop guidance for Commonwealth''s Attorneys regarding federal civil immigration arrests in their offices.", "Department of Elections to develop guidance for elections officials and poll workers regarding federal civil immigration arrests at polling places.", "Virginia Department of Education, State Council of Higher Education for Virginia, and Virginia Community College System to develop guidance for schools regarding federal civil immigration arrests on their property.", "Virginia Department of Health to develop guidance for hospitals and healthcare facilities regarding federal civil immigration arrests.", "Secretary of Administration to coordinate a website outlining guidance, resources for affected individuals, and a mechanism to report alleged discriminatory practices/violations by federal agents.", "Executive Branch departments and agencies to implement directives, ensure staff awareness, and provide training for interacting with federal immigration officers."]', '2026-05-20', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/eo-16-a-safer-virginia-for-all.pdf', '{"title": "A SAFER VIRGINIA FOR ALL", "order_number": "16 (2026)", "signed_date": "2026-05-20", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order outlines the Commonwealth of Virginia''s policy regarding federal civil immigration enforcement to protect residents and guide state and local public servants. It responds to a significant increase in immigration-related detentions, including those of individuals not convicted of crimes and children, aiming to mitigate the impact of aggressive federal tactics while ensuring adherence to constitutional principles and maintaining public trust in law enforcement. The order mandates various state agencies to develop specific guidance and resources for interacting with federal immigration officers in public and non-public settings such as schools, courthouses, and polling places.", "policy_topics": ["Immigration Enforcement", "Civil Liberties", "State-Federal Relations", "Law Enforcement Policy", "Public Safety", "Education", "Healthcare", "Legal Guidance", "Community Trust"], "agencies": ["Executive Branch Departments and Agencies", "Department of Criminal Justice Services", "Commonwealth''s Attorneys'' Services Council", "Department of Elections", "Virginia Department of Education", "State Council of Higher Education for Virginia", "Virginia Community College System", "Virginia Department of Health", "Secretary of Administration", "Secretary of Public Safety and Homeland Security"], "actions_required": ["Confirm federal immigration officers possess valid warrants or orders for entering, accessing, or using nonpublic areas of Commonwealth property.", "Prohibit federal immigration officers from using nonpublic areas of Commonwealth property as a staging, processing, or operations base for civil immigration enforcement.", "Department of Criminal Justice Services to develop guidance for courthouse and courtroom security regarding federal civil immigration arrests.", "Commonwealth''s Attorneys'' Services Council to develop guidance for Commonwealth''s Attorneys regarding federal civil immigration arrests in their offices.", "Department of Elections to develop guidance for elections officials and poll workers regarding federal civil immigration arrests at polling places.", "Virginia Department of Education, State Council of Higher Education for Virginia, and Virginia Community College System to develop guidance for schools regarding federal civil immigration arrests on their property.", "Virginia Department of Health to develop guidance for hospitals and healthcare facilities regarding federal civil immigration arrests.", "Secretary of Administration to coordinate a website outlining guidance, resources for affected individuals, and a mechanism to report alleged discriminatory practices/violations by federal agents.", "Executive Branch departments and agencies to implement directives, ensure staff awareness, and provide training for interacting with federal immigration officers."], "effective_date": "2026-05-20", "source_type": "executive order"}', '2026-05-20T19:52:09+00:00', 'EXECUTIVE ORDER 16 (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (2, '15 (2026)', 'Strengthening Virginia''s Economic Competitiveness', '2026-05-07', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order establishes the Governor''s Economic Development Policy Steering Committee and directs the Virginia Economic Development Partnership (VEDP) to regularly assess the state''s economic competitiveness. It aims for a holistic approach to economic development by focusing on fostering business growth, creating opportunities for all Virginians through lower costs and expanded pathways, and positioning the Commonwealth as a leader in emerging industries and workforce transformation. The Steering Committee, comprised of the Governor''s full Cabinet, is tasked with developing a comprehensive economic development policy.', '["Economic Development", "Workforce Development", "Infrastructure", "Housing Affordability", "Childcare Costs", "Regulatory Streamlining", "Business Growth", "Innovation", "Regional Vitality", "Education", "Talent Solutions", "Research and Development", "Emerging Industries"]', '["Governor''s Economic Development Policy Steering Committee", "Virginia Economic Development Partnership (VEDP)", "Secretary of Commerce and Trade", "Secretary of Administration", "Secretary of Agriculture and Forestry", "Secretary of the Commonwealth", "Secretary of Education", "Secretary of Finance", "Secretary of Health and Human Resources", "Secretary of Labor", "Secretary of Natural and Historic Resources", "Secretary of Public Safety and Homeland Security", "Secretary of Transportation", "Secretary of Veterans and Defense Affairs", "Chief Diversity Officer", "Chief Energy Officer", "Chief Transformation Officer", "Office of the Governor", "Offices of the Secretariats"]', '["Establish a Cabinet-wide Steering Committee to lead the development of a comprehensive economic development policy for the Commonwealth.", "Direct VEDP to regularly assess Virginia''s economic competitiveness and recommend initiatives to strengthen Virginia''s competitive position.", "The Secretary of Commerce and Trade is directed to establish and chair the Economic Development Policy Steering Committee.", "The Steering Committee shall provide a report setting forth the Commonwealth''s proposed Comprehensive Economic Development Policy to the Governor by January 16, 2027.", "VEDP shall regularly assess Virginia''s economic competitiveness and recommend initiatives to strengthen workforce talent solutions, research and development, innovation, infrastructure, housing affordability, alignment between education and business needs, access to childcare, and other critical areas.", "All executive branch agencies must fully cooperate with the Steering Committee and provide input and assistance as may be requested."]', '2026-05-07', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/eo-15-strengthening-virginias-economic-competitiveness..pdf', '{"title": "Strengthening Virginia''s Economic Competitiveness", "order_number": "15 (2026)", "signed_date": "2026-05-07", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order establishes the Governor''s Economic Development Policy Steering Committee and directs the Virginia Economic Development Partnership (VEDP) to regularly assess the state''s economic competitiveness. It aims for a holistic approach to economic development by focusing on fostering business growth, creating opportunities for all Virginians through lower costs and expanded pathways, and positioning the Commonwealth as a leader in emerging industries and workforce transformation. The Steering Committee, comprised of the Governor''s full Cabinet, is tasked with developing a comprehensive economic development policy.", "policy_topics": ["Economic Development", "Workforce Development", "Infrastructure", "Housing Affordability", "Childcare Costs", "Regulatory Streamlining", "Business Growth", "Innovation", "Regional Vitality", "Education", "Talent Solutions", "Research and Development", "Emerging Industries"], "agencies": ["Governor''s Economic Development Policy Steering Committee", "Virginia Economic Development Partnership (VEDP)", "Secretary of Commerce and Trade", "Secretary of Administration", "Secretary of Agriculture and Forestry", "Secretary of the Commonwealth", "Secretary of Education", "Secretary of Finance", "Secretary of Health and Human Resources", "Secretary of Labor", "Secretary of Natural and Historic Resources", "Secretary of Public Safety and Homeland Security", "Secretary of Transportation", "Secretary of Veterans and Defense Affairs", "Chief Diversity Officer", "Chief Energy Officer", "Chief Transformation Officer", "Office of the Governor", "Offices of the Secretariats"], "actions_required": ["Establish a Cabinet-wide Steering Committee to lead the development of a comprehensive economic development policy for the Commonwealth.", "Direct VEDP to regularly assess Virginia''s economic competitiveness and recommend initiatives to strengthen Virginia''s competitive position.", "The Secretary of Commerce and Trade is directed to establish and chair the Economic Development Policy Steering Committee.", "The Steering Committee shall provide a report setting forth the Commonwealth''s proposed Comprehensive Economic Development Policy to the Governor by January 16, 2027.", "VEDP shall regularly assess Virginia''s economic competitiveness and recommend initiatives to strengthen workforce talent solutions, research and development, innovation, infrastructure, housing affordability, alignment between education and business needs, access to childcare, and other critical areas.", "All executive branch agencies must fully cooperate with the Steering Committee and provide input and assistance as may be requested."], "effective_date": "2026-05-07", "source_type": "executive order"}', '2026-05-20T19:52:14+00:00', 'EXECUTIVE ORDER 15 (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (3, '14 (2026)', 'ESTABLISHING THE ROLE OF CHIEF ENERGY OFFICER', '2026-03-25', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order establishes the position of Chief Energy Officer (CEO) within the Office of the Governor as a cabinet-level role. The CEO is tasked with navigating Virginia''s energy challenges, reducing energy bills for citizens, ensuring grid reliability, and advancing clean energy goals. The creation of this position addresses issues like rising electricity prices, rapid load growth, and the need for a unified strategy to manage the state''s energy policy objectives and improve coordination across various entities.', '["Energy policy", "Energy affordability", "Energy reliability", "Clean energy goals", "Electricity sector challenges", "Economic development", "Utility regulation", "Energy efficiency"]', '["Office of the Governor", "Virginia State Corporation Commission", "Division of Consumer Counsel", "General Assembly", "Virginia Economic Development Partnership", "Secretary of Commerce and Trade", "Department of Social Services", "Department of Housing and Community Development", "Virginia Energy"]', '["Establish the position of Chief Energy Officer within the Office of the Governor.", "Chief Energy Officer to engage with PJM and other PJM states on capacity market reforms, generator interconnection reforms, and load forecasting transparency.", "Chief Energy Officer to engage with the Virginia State Corporation Commission, public electric utilities, Division of Consumer Counsel, and stakeholders to identify solutions for reducing electric rates and ensuring fair cost allocation.", "Chief Energy Officer to engage with the General Assembly to enact and implement legislation addressing energy affordability and demand.", "Chief Energy Officer to coordinate with the Virginia Economic Development Partnership and Secretary of Commerce and Trade to scope the energy landscape for investment and business needs.", "Chief Energy Officer to coordinate with relevant state agencies and utilities to maximize customer participation in existing utility bill-lowering programs."]', '2026-03-25', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-14-ESTABLISHING-THE-ROLE-OF-CHIEF-ENERGY-OFFICER.pdf', '{"title": "ESTABLISHING THE ROLE OF CHIEF ENERGY OFFICER", "order_number": "14 (2026)", "signed_date": "2026-03-25", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order establishes the position of Chief Energy Officer (CEO) within the Office of the Governor as a cabinet-level role. The CEO is tasked with navigating Virginia''s energy challenges, reducing energy bills for citizens, ensuring grid reliability, and advancing clean energy goals. The creation of this position addresses issues like rising electricity prices, rapid load growth, and the need for a unified strategy to manage the state''s energy policy objectives and improve coordination across various entities.", "policy_topics": ["Energy policy", "Energy affordability", "Energy reliability", "Clean energy goals", "Electricity sector challenges", "Economic development", "Utility regulation", "Energy efficiency"], "agencies": ["Office of the Governor", "Virginia State Corporation Commission", "Division of Consumer Counsel", "General Assembly", "Virginia Economic Development Partnership", "Secretary of Commerce and Trade", "Department of Social Services", "Department of Housing and Community Development", "Virginia Energy"], "actions_required": ["Establish the position of Chief Energy Officer within the Office of the Governor.", "Chief Energy Officer to engage with PJM and other PJM states on capacity market reforms, generator interconnection reforms, and load forecasting transparency.", "Chief Energy Officer to engage with the Virginia State Corporation Commission, public electric utilities, Division of Consumer Counsel, and stakeholders to identify solutions for reducing electric rates and ensuring fair cost allocation.", "Chief Energy Officer to engage with the General Assembly to enact and implement legislation addressing energy affordability and demand.", "Chief Energy Officer to coordinate with the Virginia Economic Development Partnership and Secretary of Commerce and Trade to scope the energy landscape for investment and business needs.", "Chief Energy Officer to coordinate with relevant state agencies and utilities to maximize customer participation in existing utility bill-lowering programs."], "effective_date": "2026-03-25", "source_type": "executive order"}', '2026-05-20T19:52:18+00:00', 'EXECUTIVE ORDER 14 (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (4, '13', 'ENSURING SECURE, ACCURATE, AND FAIR ELECTIONS', '2026-03-24', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order reaffirms Virginia''s commitment to secure, accurate, and fair elections by ensuring eligible voters can register and cast ballots without fear of being removed from voter rolls due to inaccurate information. It directs the Department of Elections to annually certify election security procedures, voter list maintenance, and initiate the process of rejoining the Electronic Registration Information Center (ERIC) to improve data accuracy. The order also mandates an awareness campaign for election-related offenses and a review of federal data-sharing partnerships to enhance election integrity.', '["election security", "voter registration", "voter list maintenance", "election integrity", "data sharing", "election administration"]', '["Office of the Governor", "Department of Elections", "Department of Motor Vehicles", "Electronic Registration Information Center (ERIC)", "Department of Homeland Security", "Social Security Administration", "United States Election Assistance Commission", "Electoral Boards"]', '["Commissioner of Department of Elections to annually certify election security procedures, including ballot security, counting machine testing, and election result accuracy, as well as the training of general registrars.", "Commissioner of Department of Elections to annually certify the completion of systematic programs to remove ineligible voters from the registration system at least 90 days before federal elections.", "Commissioner of Department of Elections to annually certify the use of all four ''list maintenance'' reports provided by ERIC and information from other states.", "Commissioner of Department of Elections to annually certify the daily receipt and action on information from the Department of Motor Vehicles and other state agencies regarding new eligible voters, movers, deceased voters, and ineligible voters.", "Commissioner of Department of Motor Vehicles to annually certify daily data sharing with the Department of Elections.", "Commissioner of Department of Motor Vehicles to annually certify the verification of applicant''s identity and legal status with DHS SAVE and SSA databases when issuing credentials.", "Commissioner of Department of Motor Vehicles to annually certify that public forms are available translated into required languages and to update questionnaires for voter information.", "Department of Elections to encourage and provide information to general registrars and voters regarding election-related offenses and their punishments.", "All state agencies that register individuals to vote to post information regarding election-related offenses.", "Commissioner of Department of Elections to certify within 30 days that Virginia has started the process to rejoin ERIC.", "Commissioner of Department of Elections to review all ongoing partnerships with the U.S. Department of Homeland Security and the U.S. Election Assistance Commission regarding data sharing compliance and necessity after Virginia rejoins ERIC."]', '2026-03-24', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-13-Ensuring-Secure,-Accurate,-and-Fair-Elections.pdf', '{"title": "ENSURING SECURE, ACCURATE, AND FAIR ELECTIONS", "order_number": "13", "signed_date": "2026-03-24", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order reaffirms Virginia''s commitment to secure, accurate, and fair elections by ensuring eligible voters can register and cast ballots without fear of being removed from voter rolls due to inaccurate information. It directs the Department of Elections to annually certify election security procedures, voter list maintenance, and initiate the process of rejoining the Electronic Registration Information Center (ERIC) to improve data accuracy. The order also mandates an awareness campaign for election-related offenses and a review of federal data-sharing partnerships to enhance election integrity.", "policy_topics": ["election security", "voter registration", "voter list maintenance", "election integrity", "data sharing", "election administration"], "agencies": ["Office of the Governor", "Department of Elections", "Department of Motor Vehicles", "Electronic Registration Information Center (ERIC)", "Department of Homeland Security", "Social Security Administration", "United States Election Assistance Commission", "Electoral Boards"], "actions_required": ["Commissioner of Department of Elections to annually certify election security procedures, including ballot security, counting machine testing, and election result accuracy, as well as the training of general registrars.", "Commissioner of Department of Elections to annually certify the completion of systematic programs to remove ineligible voters from the registration system at least 90 days before federal elections.", "Commissioner of Department of Elections to annually certify the use of all four ''list maintenance'' reports provided by ERIC and information from other states.", "Commissioner of Department of Elections to annually certify the daily receipt and action on information from the Department of Motor Vehicles and other state agencies regarding new eligible voters, movers, deceased voters, and ineligible voters.", "Commissioner of Department of Motor Vehicles to annually certify daily data sharing with the Department of Elections.", "Commissioner of Department of Motor Vehicles to annually certify the verification of applicant''s identity and legal status with DHS SAVE and SSA databases when issuing credentials.", "Commissioner of Department of Motor Vehicles to annually certify that public forms are available translated into required languages and to update questionnaires for voter information.", "Department of Elections to encourage and provide information to general registrars and voters regarding election-related offenses and their punishments.", "All state agencies that register individuals to vote to post information regarding election-related offenses.", "Commissioner of Department of Elections to certify within 30 days that Virginia has started the process to rejoin ERIC.", "Commissioner of Department of Elections to review all ongoing partnerships with the U.S. Department of Homeland Security and the U.S. Election Assistance Commission regarding data sharing compliance and necessity after Virginia rejoins ERIC."], "effective_date": "2026-03-24", "source_type": "executive order"}', '2026-05-20T19:52:25+00:00', 'NUMBER 13 (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (5, 'Eleven (2026)', 'Declaration of a State of Emergency Due to Severe Winter Weather', '2026-01-22', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order declares a state of emergency in Virginia due to a severe winter storm expected on January 24-25, 2026, bringing significant snow, ice, and freezing temperatures, potentially causing transportation issues and power outages. It directs state and local governments to mobilize resources, activate emergency plans, and coordinate response and recovery efforts. The order also activates price gouging laws and authorizes up to $2,750,000 in funds for emergency operations.', '["Emergency Management", "Winter Weather", "State of Emergency", "Disaster Response", "Public Safety", "Price Gouging", "Government Operations", "Funding"]', '["National Weather Service", "Virginia Emergency Operations Center (VEOC)", "Virginia Emergency Support Team", "Virginia Department of Emergency Management", "Department of Military Affairs", "Virginia National Guard"]', '["Implement the Commonwealth of Virginia Emergency Operations Plan and other state plans.", "Activate the Virginia Emergency Operations Center and Virginia Emergency Support Team, and activate the Emergency Management Assistance Compact as needed.", "Authorize heads of executive branch agencies to waive state requirements/regulations, enter contracts without normal procedures, and forgo application/permit fees or royalties.", "Activate § 59.1-525 et seq. of the Code of Virginia related to price gouging.", "Authorize $2,750,000 in state sum sufficient funds for state and local government mission assignments and response/recovery operations, including $1,000,000 for the Department of Military Affairs.", "Activate the Virginia National Guard to State Active Duty."]', '2026-01-22', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-11-Declaring-State-of-Emergency---2026-January-Winter-Weather.pdf', '{"title": "Declaration of a State of Emergency Due to Severe Winter Weather", "order_number": "Eleven (2026)", "signed_date": "2026-01-22", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order declares a state of emergency in Virginia due to a severe winter storm expected on January 24-25, 2026, bringing significant snow, ice, and freezing temperatures, potentially causing transportation issues and power outages. It directs state and local governments to mobilize resources, activate emergency plans, and coordinate response and recovery efforts. The order also activates price gouging laws and authorizes up to $2,750,000 in funds for emergency operations.", "policy_topics": ["Emergency Management", "Winter Weather", "State of Emergency", "Disaster Response", "Public Safety", "Price Gouging", "Government Operations", "Funding"], "agencies": ["National Weather Service", "Virginia Emergency Operations Center (VEOC)", "Virginia Emergency Support Team", "Virginia Department of Emergency Management", "Department of Military Affairs", "Virginia National Guard"], "actions_required": ["Implement the Commonwealth of Virginia Emergency Operations Plan and other state plans.", "Activate the Virginia Emergency Operations Center and Virginia Emergency Support Team, and activate the Emergency Management Assistance Compact as needed.", "Authorize heads of executive branch agencies to waive state requirements/regulations, enter contracts without normal procedures, and forgo application/permit fees or royalties.", "Activate § 59.1-525 et seq. of the Code of Virginia related to price gouging.", "Authorize $2,750,000 in state sum sufficient funds for state and local government mission assignments and response/recovery operations, including $1,000,000 for the Department of Military Affairs.", "Activate the Virginia National Guard to State Active Duty."], "effective_date": "2026-01-22", "source_type": "executive order"}', '2026-05-20T19:52:28+00:00', 'NUMBER ELEVEN (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (6, '10 (2026)', 'Rescission of Executive Order No. Forty Seven (2025)', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order (Number Ten, 2026) rescinds Executive Order No. 47 (2025), which had previously directed state and local law enforcement to use resources for enforcing federal civil immigration laws. The rescission emphasizes that federal authorities should enforce federal immigration laws, and that state and local law enforcement should focus on core responsibilities such as investigating criminal activity, staffing jails, and community engagement. It declares that diverting state or local resources for federal immigration enforcement is not an appropriate use of state or local resources.', '["Immigration", "Law Enforcement", "Public Safety", "State-Federal Relations"]', '["state and local law enforcement", "federal authorities"]', '["Rescind Executive Order No. 47 (2025)", "State and local law enforcement to cease diverting resources for federal civil immigration law enforcement", "State and local law enforcement to prioritize public safety, criminal investigations, jail staffing, community engagement, and enforcement of local and state laws"]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-10-RESCISSION-OF-EXECUTIVE-ORDER-NO.-FORTY-SEVEN.pdf', '{"title": "Rescission of Executive Order No. Forty Seven (2025)", "order_number": "10 (2026)", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order (Number Ten, 2026) rescinds Executive Order No. 47 (2025), which had previously directed state and local law enforcement to use resources for enforcing federal civil immigration laws. The rescission emphasizes that federal authorities should enforce federal immigration laws, and that state and local law enforcement should focus on core responsibilities such as investigating criminal activity, staffing jails, and community engagement. It declares that diverting state or local resources for federal immigration enforcement is not an appropriate use of state or local resources.", "policy_topics": ["Immigration", "Law Enforcement", "Public Safety", "State-Federal Relations"], "agencies": ["state and local law enforcement", "federal authorities"], "actions_required": ["Rescind Executive Order No. 47 (2025)", "State and local law enforcement to cease diverting resources for federal civil immigration law enforcement", "State and local law enforcement to prioritize public safety, criminal investigations, jail staffing, community engagement, and enforcement of local and state laws"], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:33+00:00', 'NUMBER TEN (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (7, '8', 'AUTHORITY AND RESPONSIBILITY OF THE CHIEF OF STAFF', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order from Governor Abigail D. Spanberger of Virginia delegates specific powers and duties to the Chief of Staff. It primarily authorizes the Chief of Staff to direct the administration of the state''s planning, budget, and personnel systems, serving as deputy planning and budget officer and deputy personnel officer respectively. The order also assigns the Chief of Staff review responsibilities for critical matters and inter-cabinet differences during the Governor''s absence, and oversight of the Office of the Governor, while explicitly retaining ultimate authority and certain key decisions with the Governor.', '["Government Administration", "Budgeting", "Personnel Management", "Delegation of Authority", "State Government Operations"]', '["General Assembly", "Office of the Governor"]', '["Chief of Staff (CoS) to direct administration of the state government planning and budget process (as deputy planning and budget officer), with specific exclusions retained by the Governor.", "CoS to direct administration of the state government personnel system (as deputy personnel officer), with specific exclusions retained by the Governor.", "CoS to review major planning, budgetary, personnel, policy, and legislative matters that require the Governor''s decision, in the event of the Governor''s absence or unavailability.", "CoS to review policy or operational differences that may arise among or between Secretaries and other Cabinet members, in the event of the Governor''s absence or unavailability.", "CoS to administer the direction and supervision of the Office of the Governor, including its budgetary and personnel authority."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-8-Authority-and-Responsibility-of-the-Chief-of-Staff.pdf', '{"title": "AUTHORITY AND RESPONSIBILITY OF THE CHIEF OF STAFF", "order_number": "8", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order from Governor Abigail D. Spanberger of Virginia delegates specific powers and duties to the Chief of Staff. It primarily authorizes the Chief of Staff to direct the administration of the state''s planning, budget, and personnel systems, serving as deputy planning and budget officer and deputy personnel officer respectively. The order also assigns the Chief of Staff review responsibilities for critical matters and inter-cabinet differences during the Governor''s absence, and oversight of the Office of the Governor, while explicitly retaining ultimate authority and certain key decisions with the Governor.", "policy_topics": ["Government Administration", "Budgeting", "Personnel Management", "Delegation of Authority", "State Government Operations"], "agencies": ["General Assembly", "Office of the Governor"], "actions_required": ["Chief of Staff (CoS) to direct administration of the state government planning and budget process (as deputy planning and budget officer), with specific exclusions retained by the Governor.", "CoS to direct administration of the state government personnel system (as deputy personnel officer), with specific exclusions retained by the Governor.", "CoS to review major planning, budgetary, personnel, policy, and legislative matters that require the Governor''s decision, in the event of the Governor''s absence or unavailability.", "CoS to review policy or operational differences that may arise among or between Secretaries and other Cabinet members, in the event of the Governor''s absence or unavailability.", "CoS to administer the direction and supervision of the Office of the Governor, including its budgetary and personnel authority."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:36+00:00', 'NUMBER EIGHT (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (8, '7', 'DELEGATING THE GOVERNOR''S AUTHORITY TO DECLARE A STATE OF EMERGENCY, TO CALL THE VIRGINIA NATIONAL GUARD TO ACTIVE SERVICE FOR EMERGENCIES OR DISASTERS, AND TO DECLARE THE GOVERNOR UNABLE TO DISCHARGE THE POWERS AND DUTIES OF HER OFFICE WHEN THE GOVERNOR CANNOT BE REACHED OR IS INCAPACITATED', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order from the Governor of Virginia, Abigail D. Spanberger, delegates critical authorities to a specified protocol of officials, starting with the Chief of Staff. These delegated powers include declaring a state of emergency, activating the Virginia National Guard for emergencies, and formally declaring the Governor unable to perform duties if she is unreachable or incapacitated for over 24 hours. This delegation is a standby measure designed to ensure continuous government function during unforeseen crises and is subject to the Governor''s ultimate authority.', '["Emergency Management", "Delegation of Authority", "State Government Operations", "Disaster Response", "National Guard Activation"]', '["Office of the Governor", "Secretary of Public Safety and Homeland Security", "Virginia Department of Emergency Management", "Secretary of Veterans and Defense Affairs", "Virginia National Guard", "Virginia Senate", "Virginia House of Delegates", "Attorney General"]', '["Chief of Staff (and subsequent officials in protocol) is delegated authority to declare a state of emergency and call forth the Virginia National Guard under specified circumstances.", "Chief of Staff (and subsequent officials in protocol) is delegated authority to transmit a declaration that the Governor is unable to discharge duties to the President pro tempore of the Senate and the Speaker of the House of Delegates, under specific conditions.", "If delegated authority is used, the Lieutenant Governor and Governor must be informed as soon as practicable."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-7-Delegating-Emergency-and-Succession-Authority-of-the-Governor.pdf', '{"title": "DELEGATING THE GOVERNOR''S AUTHORITY TO DECLARE A STATE OF EMERGENCY, TO CALL THE VIRGINIA NATIONAL GUARD TO ACTIVE SERVICE FOR EMERGENCIES OR DISASTERS, AND TO DECLARE THE GOVERNOR UNABLE TO DISCHARGE THE POWERS AND DUTIES OF HER OFFICE WHEN THE GOVERNOR CANNOT BE REACHED OR IS INCAPACITATED", "order_number": "7", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order from the Governor of Virginia, Abigail D. Spanberger, delegates critical authorities to a specified protocol of officials, starting with the Chief of Staff. These delegated powers include declaring a state of emergency, activating the Virginia National Guard for emergencies, and formally declaring the Governor unable to perform duties if she is unreachable or incapacitated for over 24 hours. This delegation is a standby measure designed to ensure continuous government function during unforeseen crises and is subject to the Governor''s ultimate authority.", "policy_topics": ["Emergency Management", "Delegation of Authority", "State Government Operations", "Disaster Response", "National Guard Activation"], "agencies": ["Office of the Governor", "Secretary of Public Safety and Homeland Security", "Virginia Department of Emergency Management", "Secretary of Veterans and Defense Affairs", "Virginia National Guard", "Virginia Senate", "Virginia House of Delegates", "Attorney General"], "actions_required": ["Chief of Staff (and subsequent officials in protocol) is delegated authority to declare a state of emergency and call forth the Virginia National Guard under specified circumstances.", "Chief of Staff (and subsequent officials in protocol) is delegated authority to transmit a declaration that the Governor is unable to discharge duties to the President pro tempore of the Senate and the Speaker of the House of Delegates, under specific conditions.", "If delegated authority is used, the Lieutenant Governor and Governor must be informed as soon as practicable."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:39+00:00', 'NUMBER SEVEN (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (9, '6', 'EVALUATING THE APPOINTMENT PROCESS TO THE BOARDS OF VISITORS FOR PUBLIC INSTITUTIONS OF HIGHER EDUCATION', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This executive order directs the Virginia Secretary of Education, in collaboration with the Secretary of the Commonwealth, to evaluate and report on the appointment process for Boards of Visitors at public higher education institutions. The report must include recommendations for legislative and policy changes regarding term lengths, reappointment, and the evaluation of potential appointees by the Virginia Commission on Higher Education Board Appointments. This initiative aims to strengthen governance and ensure the continued excellence and independence of the Commonwealth''s higher education system.', '["Higher Education", "Appointments", "Governance", "Public Institutions"]', '["Secretary of Education", "Secretary of the Commonwealth", "Virginia Commission on Higher Education Board Appointments", "Office of the Governor"]', '["Secretary of Education, in consultation with the Secretary of the Commonwealth, to prepare a report and recommendations on changes to the Board of Visitors appointment process for public institutions of higher education.", "The report must specifically address recommended legislative changes to the Board of Visitors appointment process, including term length for members, reappointment process, and term start for new members.", "The report must specifically address recommended legislative or policy changes to the process used by the Virginia Commission on Higher Education Board Appointments to evaluate potential appointees under § 2.2-2521 of the Code of Virginia.", "The report and recommendations shall be provided to the Office of the Governor within 60 days of the effective date of this Executive Order."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-6-Evaluating-Appointments-to-Public-University-Boards.pdf', '{"title": "EVALUATING THE APPOINTMENT PROCESS TO THE BOARDS OF VISITORS FOR PUBLIC INSTITUTIONS OF HIGHER EDUCATION", "order_number": "6", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This executive order directs the Virginia Secretary of Education, in collaboration with the Secretary of the Commonwealth, to evaluate and report on the appointment process for Boards of Visitors at public higher education institutions. The report must include recommendations for legislative and policy changes regarding term lengths, reappointment, and the evaluation of potential appointees by the Virginia Commission on Higher Education Board Appointments. This initiative aims to strengthen governance and ensure the continued excellence and independence of the Commonwealth''s higher education system.", "policy_topics": ["Higher Education", "Appointments", "Governance", "Public Institutions"], "agencies": ["Secretary of Education", "Secretary of the Commonwealth", "Virginia Commission on Higher Education Board Appointments", "Office of the Governor"], "actions_required": ["Secretary of Education, in consultation with the Secretary of the Commonwealth, to prepare a report and recommendations on changes to the Board of Visitors appointment process for public institutions of higher education.", "The report must specifically address recommended legislative changes to the Board of Visitors appointment process, including term length for members, reappointment process, and term start for new members.", "The report must specifically address recommended legislative or policy changes to the process used by the Virginia Commission on Higher Education Board Appointments to evaluate potential appointees under § 2.2-2521 of the Code of Virginia.", "The report and recommendations shall be provided to the Office of the Governor within 60 days of the effective date of this Executive Order."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:41+00:00', 'NUMBER SIX (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (10, '5 (2026)', 'ESTABLISHING AN ECONOMIC RESILIENCY TASK FORCE TO ADDRESS IMPACTS OF FEDERAL ACTIONS ON VIRGINIA''S ECONOMY AND WORKFORCE', '2026-01-17', 'Abigail D. Spanberger', 'state', 'This Executive Order establishes an Economic Resiliency Task Force in Virginia to counter the negative economic and workforce impacts stemming from federal actions, including job losses, funding cuts, tariffs, and immigration policy changes. It directs state agencies to develop strategies to support displaced federal employees, boost agricultural exports, and mitigate the effects of new federal work requirements on Medicaid and SNAP beneficiaries, aiming to enhance the Commonwealth''s overall economic resilience. Various reports and action plans are mandated to be delivered to the Governor''s Office.', '["Economic Development", "Workforce Development", "Federal-State Relations", "Trade Policy", "Immigration", "Public Assistance Programs", "Agriculture", "Employment Services", "Public-Private Partnerships"]', '["Office of the Governor", "Economic Resiliency Task Force", "Secretary of Commerce and Trade", "Secretary of Finance", "Secretary of Labor", "Secretary of Administration", "Secretary of Health and Human Resources", "Secretary of Agriculture", "Secretary of Education", "Virginia Works", "Virginia Employment Commission", "Virginia Office of Education Economics", "Department of Agriculture and Consumer Services", "Virginia Economic Development Partnership", "Port of Virginia"]', '["Establish the Economic Resiliency Task Force, chaired by the Secretary of Commerce and Trade, with members including Secretaries of Finance, Labor, Administration, Health and Human Resources, Agriculture, Education, or their designees, and other relevant executive branch agencies.", "Secretary of Finance to create a tracker for federal rescissions across state government for calendar years 2025 and 2026, due within 90 days of the effective date.", "Task Force to deliver an action plan to the Office of the Governor by June 1, 2026, including recommendations to mitigate harm from federal rescissions and long-term economic resiliency strategies.", "All executive branch agencies to provide support to the Task Force upon request.", "Secretary of Health and Human Resources, in coordination with Secretaries of Administration, Finance, Labor, and Education, to form a cross-Secretariat working group on Medicaid and SNAP work requirements implementation.", "Cross-Secretariat working group to conduct a readiness assessment of relevant executive branch agencies for Medicaid work requirements.", "Cross-Secretariat working group to develop and recommend strategies for compliance with work requirements, maximizing exemptions, stabilizing eligibility workforce, modernizing systems, and publishing performance metrics.", "Cross-Secretariat working group to deliver a report on the results of the readiness assessment and subsequent recommendations to the Office of the Governor within 60 days of the effective date.", "Virginia Works, in coordination with the Virginia Employment Commission, the Secretary of Commerce and Trade, and the Virginia Office of Education Economics, to develop and report on innovative, data-driven approaches to expanding job opportunities for fired federal employees and contractors within 90 days.", "Virginia Works to identify potential private sector partnerships and facilitate public-private partnerships for job placement of Virginia workers.", "Virginia Works to submit a report on legislative or regulatory changes necessary for public-private partnerships within 60 days.", "Department of Agriculture and Consumer Services to collaborate with the Virginia Economic Development Partnership and the Port of Virginia on strategies to grow Virginia agricultural and forestry exports.", "Department of Agriculture and Consumer Services, in consultation with VEDP and Port of Virginia, to submit a report to the Office of the Governor within 90 days with recommendations for growing exports and mitigating tariff impacts."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-5-Establishing-an-Economic-Resiliency-Task-Force-for-Virginia.pdf', '{"title": "ESTABLISHING AN ECONOMIC RESILIENCY TASK FORCE TO ADDRESS IMPACTS OF FEDERAL ACTIONS ON VIRGINIA''S ECONOMY AND WORKFORCE", "order_number": "5 (2026)", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "state", "summary": "This Executive Order establishes an Economic Resiliency Task Force in Virginia to counter the negative economic and workforce impacts stemming from federal actions, including job losses, funding cuts, tariffs, and immigration policy changes. It directs state agencies to develop strategies to support displaced federal employees, boost agricultural exports, and mitigate the effects of new federal work requirements on Medicaid and SNAP beneficiaries, aiming to enhance the Commonwealth''s overall economic resilience. Various reports and action plans are mandated to be delivered to the Governor''s Office.", "policy_topics": ["Economic Development", "Workforce Development", "Federal-State Relations", "Trade Policy", "Immigration", "Public Assistance Programs", "Agriculture", "Employment Services", "Public-Private Partnerships"], "agencies": ["Office of the Governor", "Economic Resiliency Task Force", "Secretary of Commerce and Trade", "Secretary of Finance", "Secretary of Labor", "Secretary of Administration", "Secretary of Health and Human Resources", "Secretary of Agriculture", "Secretary of Education", "Virginia Works", "Virginia Employment Commission", "Virginia Office of Education Economics", "Department of Agriculture and Consumer Services", "Virginia Economic Development Partnership", "Port of Virginia"], "actions_required": ["Establish the Economic Resiliency Task Force, chaired by the Secretary of Commerce and Trade, with members including Secretaries of Finance, Labor, Administration, Health and Human Resources, Agriculture, Education, or their designees, and other relevant executive branch agencies.", "Secretary of Finance to create a tracker for federal rescissions across state government for calendar years 2025 and 2026, due within 90 days of the effective date.", "Task Force to deliver an action plan to the Office of the Governor by June 1, 2026, including recommendations to mitigate harm from federal rescissions and long-term economic resiliency strategies.", "All executive branch agencies to provide support to the Task Force upon request.", "Secretary of Health and Human Resources, in coordination with Secretaries of Administration, Finance, Labor, and Education, to form a cross-Secretariat working group on Medicaid and SNAP work requirements implementation.", "Cross-Secretariat working group to conduct a readiness assessment of relevant executive branch agencies for Medicaid work requirements.", "Cross-Secretariat working group to develop and recommend strategies for compliance with work requirements, maximizing exemptions, stabilizing eligibility workforce, modernizing systems, and publishing performance metrics.", "Cross-Secretariat working group to deliver a report on the results of the readiness assessment and subsequent recommendations to the Office of the Governor within 60 days of the effective date.", "Virginia Works, in coordination with the Virginia Employment Commission, the Secretary of Commerce and Trade, and the Virginia Office of Education Economics, to develop and report on innovative, data-driven approaches to expanding job opportunities for fired federal employees and contractors within 90 days.", "Virginia Works to identify potential private sector partnerships and facilitate public-private partnerships for job placement of Virginia workers.", "Virginia Works to submit a report on legislative or regulatory changes necessary for public-private partnerships within 60 days.", "Department of Agriculture and Consumer Services to collaborate with the Virginia Economic Development Partnership and the Port of Virginia on strategies to grow Virginia agricultural and forestry exports.", "Department of Agriculture and Consumer Services, in consultation with VEDP and Port of Virginia, to submit a report to the Office of the Governor within 90 days with recommendations for growing exports and mitigating tariff impacts."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:45+00:00', 'NUMBER FIVE (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (11, 'NUMBER FOUR (2026)', 'COMMITTING TO ACADEMIC EXCELLENCE AND AFFIRMING THE COMMONWEALTH''S COMMITMENT TO PROVIDING A HIGH-QUALITY PUBLIC EDUCATION FOR ALL STUDENTS', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This executive order outlines a comprehensive approach to academic excellence in Virginia, focusing on improving literacy and mathematics outcomes for all students. It directs various actions, including a statewide listening tour, strengthening the Virginia Literacy Act, enhancing math education, refining school accountability systems, and affirming the rights of students, parents, and teachers. The order emphasizes addressing learning disparities and providing high-quality public education in a supportive environment.', '["Education", "Academic Excellence", "Literacy", "Mathematics Education", "School Accountability", "Student Rights", "Parental Rights", "Teacher Rights", "Educational Equity", "Assessment"]', '["Office of the Governor", "Department of Education", "Superintendent of Public Instruction", "Board of Education", "JLARC", "WestEd"]', '["Secretary of Education and Superintendent of Public Instruction to host a statewide listening tour within 100 days of the order and report findings to the Governor.", "Superintendent of Public Instruction to convene a state advisory workgroup to strengthen implementation of the Virginia Literacy Act.", "The workgroup shall recommend improvements to student reading plan processes, provide input for updating guidance, advise on VAConnects, and help elevate early literacy importance.", "Superintendent of Public Instruction to provide an update to the Office of the Governor on mathematics work (staffing, grant awards, task force report) within 30 days.", "Department of Education to expedite credentialing changes for educators teaching advanced mathematics in middle school.", "Secretary of Education and Superintendent of Public Instruction to present an after-action report on SPSF implementation lessons learned and an action plan incorporating JLARC recommendations.", "Superintendent to consistently and effectively implement a state program to support schools in need of support.", "Secretary of Education and Superintendent of Public Instruction to consult with experts and stakeholders on accountability and technical matters.", "Secretary of Education and Superintendent of Public Instruction to convene an innovative assessment workgroup within 60 days and quarterly.", "Secretary of Education and Superintendent of Public Instruction to evaluate and appoint new members to the innovative assessment workgroup.", "Secretary of Education and Superintendent of Public Instruction to support local school divisions in affirming student, parent, and teacher protections and rights through various specified means."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EXECUTIVE-ORDER-FOUR_1.17.pdf', '{"title": "COMMITTING TO ACADEMIC EXCELLENCE AND AFFIRMING THE COMMONWEALTH''S COMMITMENT TO PROVIDING A HIGH-QUALITY PUBLIC EDUCATION FOR ALL STUDENTS", "order_number": "NUMBER FOUR (2026)", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This executive order outlines a comprehensive approach to academic excellence in Virginia, focusing on improving literacy and mathematics outcomes for all students. It directs various actions, including a statewide listening tour, strengthening the Virginia Literacy Act, enhancing math education, refining school accountability systems, and affirming the rights of students, parents, and teachers. The order emphasizes addressing learning disparities and providing high-quality public education in a supportive environment.", "policy_topics": ["Education", "Academic Excellence", "Literacy", "Mathematics Education", "School Accountability", "Student Rights", "Parental Rights", "Teacher Rights", "Educational Equity", "Assessment"], "agencies": ["Office of the Governor", "Department of Education", "Superintendent of Public Instruction", "Board of Education", "JLARC", "WestEd"], "actions_required": ["Secretary of Education and Superintendent of Public Instruction to host a statewide listening tour within 100 days of the order and report findings to the Governor.", "Superintendent of Public Instruction to convene a state advisory workgroup to strengthen implementation of the Virginia Literacy Act.", "The workgroup shall recommend improvements to student reading plan processes, provide input for updating guidance, advise on VAConnects, and help elevate early literacy importance.", "Superintendent of Public Instruction to provide an update to the Office of the Governor on mathematics work (staffing, grant awards, task force report) within 30 days.", "Department of Education to expedite credentialing changes for educators teaching advanced mathematics in middle school.", "Secretary of Education and Superintendent of Public Instruction to present an after-action report on SPSF implementation lessons learned and an action plan incorporating JLARC recommendations.", "Superintendent to consistently and effectively implement a state program to support schools in need of support.", "Secretary of Education and Superintendent of Public Instruction to consult with experts and stakeholders on accountability and technical matters.", "Secretary of Education and Superintendent of Public Instruction to convene an innovative assessment workgroup within 60 days and quarterly.", "Secretary of Education and Superintendent of Public Instruction to evaluate and appoint new members to the innovative assessment workgroup.", "Secretary of Education and Superintendent of Public Instruction to support local school divisions in affirming student, parent, and teacher protections and rights through various specified means."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:48+00:00', 'NUMBER FOUR (2026)  COMMITTING TO ACADEMIC EXCELLENCE AND AFFIRMING THE COMMONWEALTH’S COMMITMENT TO PROVIDING A HIGH-QUALITY PUBLIC EDUCATION FOR ALL STUDENTS  By virtue of the authority vested in me as Governor under Article V of the Constitution of Virginia and under the laws of the Commonwealth, including, but not limited to, §§ 2.2-103 and 2.2-110 of the Code of Virginia, I hereby announce a comprehensive approach to academic excellence in the Commonwealth and affirm the rights of parents, students, and teachers to a high-quality public education in a safe and welcoming environment conducive to learning. Importance of the Initiative Every child, along with their parents and guardians, deserves the assurance that their education will meet rigorous standards and equip them with the knowledge and skills needed for a successful future. As such, the Virginia Constitution directs the Commonwealth to seek to ensure its public schools deliver a high-quality education. Yet, despite progress, Virginia still has meaningful work to do.  Thanks to the dedicated efforts of our educators, principals, and school system leaders, Virginia has made significant gains in literacy since the General Assembly passed the landmark Virginia Literacy Act in 2022. However, far too many students still struggle to read at grade level. In the 2024-2025 school year, less than three-quarters of Virginia students met state benchmarks on the Standards of Learning (SOL) reading assessment. Rates are even lower for students who are low-income, Black, Hispanic, or have disabilities.
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (12, 'THREE (2026)', 'LOWERING THE COST OF HOUSING BY INCREASING SUPPLY', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order establishes a comprehensive process to address housing affordability and increase housing supply in Virginia. It directs key state secretaries and agencies to review and streamline regulations, permitting processes, and inter-agency coordination that impede housing production. Additionally, it creates the Commission on Unlocking Housing Production to advise on legislative, regulatory, and administrative reforms needed to facilitate the development of affordable homes across the Commonwealth.', '["Housing Affordability", "Housing Supply", "Regulatory Reform", "Permitting Streamlining", "Economic Development", "State Government Efficiency"]', '["Office of the Governor", "Secretary of Commerce and Trade", "Secretary of Natural and Historic Resources", "Secretary of Transportation", "Department of Housing and Community Development (DHCD)", "Department of Environmental Quality (DEQ)", "Department of Transportation (VDOT)", "Department of Wildlife Resources (DWR)", "Department of Conservation and Recreation (DCR)", "Department of Historic Resources (DHR)", "Virginia Economic Development Partnership", "Virginia Department of Education", "Virginia Resources Authority", "Virginia Department of Taxation", "Department of General Services"]', '["The Secretary of Commerce and Trade, the Secretary of Natural and Historic Resources, and the Secretary of Transportation are designated as Co-Lead Secretaries responsible for implementation oversight and interagency coordination.", "Co-Lead Secretaries must direct ''Covered Agencies'' (DHCD, DEQ, VDOT, DWR, DCR, DHR) to conduct a comprehensive review of their regulations, guidance documents, policies, procedures, and administrative practices affecting residential land development and housing construction.", "Covered Agencies must identify and eliminate unnecessary, duplicative, or outdated requirements; improve permitting efficiency, predictability, and transparency; streamline coordination between agencies and state/local authorities; and remove regulatory barriers impeding labor recruitment, materials sourcing, and workforce retention.", "Each Covered Agency must submit a written report within 90 days to the Co-Lead Secretaries and the Office of the Governor, detailing identified items for amendment/repeal/streamlining, with rationales, impacts, and implementation needs.", "Covered Agencies must provide recommendations to improve coordination and predictability, including consolidating permitting processes, improving state/local coordination, establishing predictable timelines, and expanding standardized review tools.", "The Co-Lead Secretaries must jointly submit a final comprehensive written report to the Office of the Governor within 120 days based on the agencies'' reports.", "Establish the Commission on Unlocking Housing Production, chaired by the Secretary of Commerce and Trade, to advise on revising state laws, regulations, and administrative practices to increase housing production.", "The Commission must review agency reports and provide ongoing updates to the Governor every six months on housing production, barriers, and suggestions for legislative, regulatory, and administrative changes."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EXECUTIVE-ORDER-THREE_1.17.pdf', '{"title": "LOWERING THE COST OF HOUSING BY INCREASING SUPPLY", "order_number": "THREE (2026)", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order establishes a comprehensive process to address housing affordability and increase housing supply in Virginia. It directs key state secretaries and agencies to review and streamline regulations, permitting processes, and inter-agency coordination that impede housing production. Additionally, it creates the Commission on Unlocking Housing Production to advise on legislative, regulatory, and administrative reforms needed to facilitate the development of affordable homes across the Commonwealth.", "policy_topics": ["Housing Affordability", "Housing Supply", "Regulatory Reform", "Permitting Streamlining", "Economic Development", "State Government Efficiency"], "agencies": ["Office of the Governor", "Secretary of Commerce and Trade", "Secretary of Natural and Historic Resources", "Secretary of Transportation", "Department of Housing and Community Development (DHCD)", "Department of Environmental Quality (DEQ)", "Department of Transportation (VDOT)", "Department of Wildlife Resources (DWR)", "Department of Conservation and Recreation (DCR)", "Department of Historic Resources (DHR)", "Virginia Economic Development Partnership", "Virginia Department of Education", "Virginia Resources Authority", "Virginia Department of Taxation", "Department of General Services"], "actions_required": ["The Secretary of Commerce and Trade, the Secretary of Natural and Historic Resources, and the Secretary of Transportation are designated as Co-Lead Secretaries responsible for implementation oversight and interagency coordination.", "Co-Lead Secretaries must direct ''Covered Agencies'' (DHCD, DEQ, VDOT, DWR, DCR, DHR) to conduct a comprehensive review of their regulations, guidance documents, policies, procedures, and administrative practices affecting residential land development and housing construction.", "Covered Agencies must identify and eliminate unnecessary, duplicative, or outdated requirements; improve permitting efficiency, predictability, and transparency; streamline coordination between agencies and state/local authorities; and remove regulatory barriers impeding labor recruitment, materials sourcing, and workforce retention.", "Each Covered Agency must submit a written report within 90 days to the Co-Lead Secretaries and the Office of the Governor, detailing identified items for amendment/repeal/streamlining, with rationales, impacts, and implementation needs.", "Covered Agencies must provide recommendations to improve coordination and predictability, including consolidating permitting processes, improving state/local coordination, establishing predictable timelines, and expanding standardized review tools.", "The Co-Lead Secretaries must jointly submit a final comprehensive written report to the Office of the Governor within 120 days based on the agencies'' reports.", "Establish the Commission on Unlocking Housing Production, chaired by the Secretary of Commerce and Trade, to advise on revising state laws, regulations, and administrative practices to increase housing production.", "The Commission must review agency reports and provide ongoing updates to the Governor every six months on housing production, barriers, and suggestions for legislative, regulatory, and administrative changes."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:52+00:00', 'NUMBER THREE (2026)  LOWERING THE COST OF HOUSING BY INCREASING SUPPLY   By virtue of the authority vested in me as Governor under Article V of the Constitution of Virginia and under the laws of the Commonwealth, including, but not limited to, §§ 2.2-103 and 2.2-110 of the Code of Virginia, I hereby announce a comprehensive process for addressing housing affordability for all Virginians, including establishing the Commission on Unlocking Housing Production and directing the Secretary of Commerce and Trade, the Secretary of Natural and Historic Resources, and the Secretary of Transportation to establish and lead a comprehensive process to address expedited housing production in Virginia. Importance of the Initiative          Across Virginia, housing costs are rising faster than incomes and supply is not keeping pace with demand. Virginia faces a deficit of nearly 300,000 affordable rental homes, and thousands of supported rental homes are at risk of losing their affordability covenants in the next 5 years. At the same time, Virginia’s median home price is now over $400,000, putting homeownership out of reach for many working families. Slow permitting, outdated zoning, labor shortages, and paper-based processes are driving up costs and delaying housing across the Commonwealth. As a result, a shortage of available and affordable homes creates cutthroat competition and drives up prices. This Administration will work to support, encourage, coordinate, and innovate using the fullest powers of state government in partnership with local governments and the nonprofit and private sectors to create practical solutions that meet the housing needs of Virginians.
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (13, '2', 'LOWERING THE COST OF HEALTHCARE FOR VIRGINIANS AND MAXIMIZING TAXPAYER DOLLARS TO SAVE THE COMMONWEALTH AND ITS CONSTITUENTS MONEY', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This executive order establishes the Interagency Health Financing Task Force in Virginia to lower healthcare costs for residents and maximize taxpayer dollars. The task force is directed to create a coordinated, cross-agency financing strategy that leverages federal funds, eliminates duplicative spending, and improves efficiency within the health and human resources system. Its objective is to ensure healthcare affordability and strengthen Virginia''s long-term healthcare infrastructure, including behavioral health and workforce development.', '["Healthcare affordability", "Health financing", "Government efficiency", "Federal funding", "Behavioral health", "Workforce development", "Data modernization"]', '["Office of the Governor", "Secretary of Health and Human Resources", "Department of Health and Human Resources", "Secretary of Finance", "Virginia Department of Medical Assistance Services", "State Health Commissioner", "Department of Behavioral Health and Developmental Sciences", "Department of Social Services", "Secretary of Administration", "Chief Transformation Officer"]', '["The Secretary of Health and Human Resources and all executive branch agencies within the Department of Health and Human Resources shall form the Interagency Health Financing Task Force.", "The Task Force shall create a financing strategy applicable to all executive branch agencies within DHHR to maximize federal funds, eliminate duplicative spending, and strengthen long-term healthcare infrastructure programs.", "The Task Force shall identify initiatives and services at risk for losing funds, inventory all health-related funding streams, review financing processes, review Managed Care Organization (MCO) performance, and identify areas of under-investment.", "The Task Force shall prepare an executive summary of its findings and recommendations to the Office of the Governor by May 1, 2026.", "The Task Force shall coordinate with the Secretary of Administration and Chief Transformation Officer to review systems and processes to avoid duplication, improve citizen experience, and identify efficiency gains.", "The Chief Transformation Officer shall deliver an initial review of healthcare systems and technology platforms and suggestions for updates to the Office of the Governor by May 1, 2026."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EXECUTIVE-ORDER-TWO_1.17.pdf', '{"title": "LOWERING THE COST OF HEALTHCARE FOR VIRGINIANS AND MAXIMIZING TAXPAYER DOLLARS TO SAVE THE COMMONWEALTH AND ITS CONSTITUENTS MONEY", "order_number": "2", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This executive order establishes the Interagency Health Financing Task Force in Virginia to lower healthcare costs for residents and maximize taxpayer dollars. The task force is directed to create a coordinated, cross-agency financing strategy that leverages federal funds, eliminates duplicative spending, and improves efficiency within the health and human resources system. Its objective is to ensure healthcare affordability and strengthen Virginia''s long-term healthcare infrastructure, including behavioral health and workforce development.", "policy_topics": ["Healthcare affordability", "Health financing", "Government efficiency", "Federal funding", "Behavioral health", "Workforce development", "Data modernization"], "agencies": ["Office of the Governor", "Secretary of Health and Human Resources", "Department of Health and Human Resources", "Secretary of Finance", "Virginia Department of Medical Assistance Services", "State Health Commissioner", "Department of Behavioral Health and Developmental Sciences", "Department of Social Services", "Secretary of Administration", "Chief Transformation Officer"], "actions_required": ["The Secretary of Health and Human Resources and all executive branch agencies within the Department of Health and Human Resources shall form the Interagency Health Financing Task Force.", "The Task Force shall create a financing strategy applicable to all executive branch agencies within DHHR to maximize federal funds, eliminate duplicative spending, and strengthen long-term healthcare infrastructure programs.", "The Task Force shall identify initiatives and services at risk for losing funds, inventory all health-related funding streams, review financing processes, review Managed Care Organization (MCO) performance, and identify areas of under-investment.", "The Task Force shall prepare an executive summary of its findings and recommendations to the Office of the Governor by May 1, 2026.", "The Task Force shall coordinate with the Secretary of Administration and Chief Transformation Officer to review systems and processes to avoid duplication, improve citizen experience, and identify efficiency gains.", "The Chief Transformation Officer shall deliver an initial review of healthcare systems and technology platforms and suggestions for updates to the Office of the Governor by May 1, 2026."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:52:57+00:00', 'NUMBER TWO (2026)  LOWERING THE COST OF HEALTHCARE FOR VIRGINIANS AND MAXIMIZING TAXPAYER DOLLARS TO SAVE THE COMMONWEALTH AND ITS CONSTITUENTS MONEY  By virtue of the authority vested in me as Governor under Article V of the Constitution of the Commonwealth of Virginia and under the laws of the Commonwealth, including, but not limited to, §§ 2.2-103 and 2.2-110 of the Code of Virginia, I hereby direct the Secretary of Health and Human Resources (the “Secretary”) and all executive branch agencies within the Department of Health and Human Resources, in coordination with other parts of the executive branch, to form the Interagency Health Financing Task Force and take action to ensure healthcare affordability for all Virginians. Importance of the Initiative  The Commonwealth’s health and human resources system is funded through a complex web of federal, state, and non-state dollars that have developed over time and are often managed in silos. This limits the Commonwealth’s ability to maximize federal matching funds and creates inefficiencies and duplicative spending. At the same time, healthcare costs continue to rise due to higher member acuity following Medicaid redeterminations and increasing pharmacy and behavioral health expenditures, placing growing pressure on the General Fund.
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (14, '1 (2026)', 'DIRECTING THE GOVERNOR''S SECRETARIES AND AGENCIES ACROSS THE COMMONWEALTH TO DETERMINE COST-SAVINGS FOR VIRGINIANS', '2026-01-17', 'Abigail D. Spanberger', 'Commonwealth of Virginia', 'Governor Abigail D. Spanberger issued Executive Order Number One (2026), directing all Governor''s Secretaries and executive branch agencies in Virginia to identify and recommend cost-saving measures for Virginians. Within 90 days, these entities must submit reports detailing changes to policies, regulations, and legislative proposals aimed at reducing costs in areas such as housing, healthcare, energy, education, childcare, and groceries to enhance affordability for residents.', '["Cost Reduction", "Affordability", "Government Efficiency", "Housing", "Healthcare", "Energy", "Education", "Childcare", "Living Expenses", "Economic Development"]', '["Governor''s Secretaries", "executive branch agencies", "Departments"]', '["Governor''s Secretaries shall prepare a report within 90 days identifying recommendations for readily implementable changes across their Departments and agencies that will reduce costs for Virginians.", "Each Secretary shall holistically review activities of their respective Secretariats to identify cost-reducing actions, policies, or changes, including evaluating actions enumerated in the Code of Virginia, published documentation, and cross-agency collaboration impacts.", "Each Secretary shall identify any pending legislative proposals that, if enacted, would readily reduce costs for Virginians.", "All executive branch agencies shall prepare a report within 90 days identifying recommendations for readily implementable changes that will reduce costs for Virginians.", "Each executive branch agency shall review all regulations, guidance, policies, procedures, and any other formal or informal agency action to identify modifications that would readily reduce costs without hindering access to or delivery of services.", "Each executive branch agency shall identify new regulations, guidance, policies, procedures, or other formal or informal agency actions that could be taken to readily reduce costs for Virginians.", "All reports shall address and specifically enumerate cost reductions for housing, healthcare, energy, education, childcare, and living expenses (e.g., groceries), and may include other cost reduction areas."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EXECUTIVE-ORDER-ONE_1.17.pdf', '{"title": "DIRECTING THE GOVERNOR''S SECRETARIES AND AGENCIES ACROSS THE COMMONWEALTH TO DETERMINE COST-SAVINGS FOR VIRGINIANS", "order_number": "1 (2026)", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Commonwealth of Virginia", "summary": "Governor Abigail D. Spanberger issued Executive Order Number One (2026), directing all Governor''s Secretaries and executive branch agencies in Virginia to identify and recommend cost-saving measures for Virginians. Within 90 days, these entities must submit reports detailing changes to policies, regulations, and legislative proposals aimed at reducing costs in areas such as housing, healthcare, energy, education, childcare, and groceries to enhance affordability for residents.", "policy_topics": ["Cost Reduction", "Affordability", "Government Efficiency", "Housing", "Healthcare", "Energy", "Education", "Childcare", "Living Expenses", "Economic Development"], "agencies": ["Governor''s Secretaries", "executive branch agencies", "Departments"], "actions_required": ["Governor''s Secretaries shall prepare a report within 90 days identifying recommendations for readily implementable changes across their Departments and agencies that will reduce costs for Virginians.", "Each Secretary shall holistically review activities of their respective Secretariats to identify cost-reducing actions, policies, or changes, including evaluating actions enumerated in the Code of Virginia, published documentation, and cross-agency collaboration impacts.", "Each Secretary shall identify any pending legislative proposals that, if enacted, would readily reduce costs for Virginians.", "All executive branch agencies shall prepare a report within 90 days identifying recommendations for readily implementable changes that will reduce costs for Virginians.", "Each executive branch agency shall review all regulations, guidance, policies, procedures, and any other formal or informal agency action to identify modifications that would readily reduce costs without hindering access to or delivery of services.", "Each executive branch agency shall identify new regulations, guidance, policies, procedures, or other formal or informal agency actions that could be taken to readily reduce costs for Virginians.", "All reports shall address and specifically enumerate cost reductions for housing, healthcare, energy, education, childcare, and living expenses (e.g., groceries), and may include other cost reduction areas."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:53:03+00:00', 'NUMBER ONE (2026)  
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (15, '1', 'DIRECTING THE COMMONWEALTH''S LAW ENFORCEMENT AGENCIES TO TERMINATE ANY AND ALL SECTION 287(g) AGREEMENTS', '2026-02-04', 'Abigail D. Spanberger', 'state', 'This executive directive mandates the termination of all Section 287(g) Agreements with U.S. Immigration and Customs Enforcement (ICE) by Virginia''s state law enforcement agencies. It reasserts that state and local resources should prioritize community safety and crime deterrence over federal civil immigration enforcement, arguing that these agreements improperly cede state authority. Agencies are also required to report their compliance within five business days.', '["immigration enforcement", "state law enforcement", "federal-state relations", "community safety"]', '["Virginia State Police", "Virginia Department of Corrections", "Virginia Department of Wildlife", "Virginia Marine Resources Commission", "U.S. Immigration and Customs Enforcement (ICE)", "Secretary of Public Safety and Homeland Security", "Secretary of Natural and Historic Resources"]', '["Virginia State Police, Virginia Department of Corrections, Virginia Department of Wildlife, and Virginia Marine Resources Commission must terminate any and all Section 287(g) Agreements and related memoranda of understanding or similar agreements with ICE.", "The aforementioned agencies must report to their respective Secretariats within five business days: (1) a list of all existing Section 287(g) Agreements and related memoranda, and (2) the date the agency formally withdrew from the identified Agreements."]', '2026-02-04', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/ed/ED-1-Directing-the-Commonwealth’s-Law-Enforcement-Agencies-to-Terminate-Any-and-All-Section-287(g)-Agreements.pdf', '{"title": "DIRECTING THE COMMONWEALTH''S LAW ENFORCEMENT AGENCIES TO TERMINATE ANY AND ALL SECTION 287(g) AGREEMENTS", "order_number": "1", "signed_date": "2026-02-04", "governor": "Abigail D. Spanberger", "jurisdiction": "state", "summary": "This executive directive mandates the termination of all Section 287(g) Agreements with U.S. Immigration and Customs Enforcement (ICE) by Virginia''s state law enforcement agencies. It reasserts that state and local resources should prioritize community safety and crime deterrence over federal civil immigration enforcement, arguing that these agreements improperly cede state authority. Agencies are also required to report their compliance within five business days.", "policy_topics": ["immigration enforcement", "state law enforcement", "federal-state relations", "community safety"], "agencies": ["Virginia State Police", "Virginia Department of Corrections", "Virginia Department of Wildlife", "Virginia Marine Resources Commission", "U.S. Immigration and Customs Enforcement (ICE)", "Secretary of Public Safety and Homeland Security", "Secretary of Natural and Historic Resources"], "actions_required": ["Virginia State Police, Virginia Department of Corrections, Virginia Department of Wildlife, and Virginia Marine Resources Commission must terminate any and all Section 287(g) Agreements and related memoranda of understanding or similar agreements with ICE.", "The aforementioned agencies must report to their respective Secretariats within five business days: (1) a list of all existing Section 287(g) Agreements and related memoranda, and (2) the date the agency formally withdrew from the identified Agreements."], "effective_date": "2026-02-04", "source_type": "executive order"}', '2026-05-20T19:53:09+00:00', 'EXECUTIVE DIRECTIVE 1 (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (16, '12 (2026)', 'PUBLIC SAFETY, CONSTITUTIONAL POLICING, AND COMMUNITY TRUST', '2026-02-04', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order establishes the Commonwealth of Virginia''s policy on public safety, constitutional policing, and community trust, directing state law enforcement agencies to align their policies with its principles. It emphasizes that law enforcement must preserve human life, protect the vulnerable, and uphold constitutional rights, fostering public trust through professionalism and transparency. The order also calls for investments in top-tier training and collaborative partnerships, while avoiding fear-based tactics and administrative enforcement of civil status. It mandates review of existing policies, training, and practices to ensure alignment with these standards and constitutional requirements.', '["Public Safety", "Constitutional Policing", "Community Trust", "Law Enforcement Standards", "Police Training", "Accountability"]', '["Secretary of Public Safety and Homeland Security", "State law enforcement agencies"]', '["The Secretary of Public Safety and Homeland Security shall support interagency coordination and the sharing of best practices consistent with these principles.", "All state law enforcement agencies shall consult with their Secretariat about strategies and approaches to strengthen community partnerships that enhance trust, safety, and problem-solving capacity.", "All state law enforcement agencies shall review policies, training, and practices to confirm alignment with this Executive Order and applicable constitutional standards."]', '2026-02-04', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/ed/EO-12-Public-Safety,-Constitutional-Policing,-and-Community-Trust.pdf', '{"title": "PUBLIC SAFETY, CONSTITUTIONAL POLICING, AND COMMUNITY TRUST", "order_number": "12 (2026)", "signed_date": "2026-02-04", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order establishes the Commonwealth of Virginia''s policy on public safety, constitutional policing, and community trust, directing state law enforcement agencies to align their policies with its principles. It emphasizes that law enforcement must preserve human life, protect the vulnerable, and uphold constitutional rights, fostering public trust through professionalism and transparency. The order also calls for investments in top-tier training and collaborative partnerships, while avoiding fear-based tactics and administrative enforcement of civil status. It mandates review of existing policies, training, and practices to ensure alignment with these standards and constitutional requirements.", "policy_topics": ["Public Safety", "Constitutional Policing", "Community Trust", "Law Enforcement Standards", "Police Training", "Accountability"], "agencies": ["Secretary of Public Safety and Homeland Security", "State law enforcement agencies"], "actions_required": ["The Secretary of Public Safety and Homeland Security shall support interagency coordination and the sharing of best practices consistent with these principles.", "All state law enforcement agencies shall consult with their Secretariat about strategies and approaches to strengthen community partnerships that enhance trust, safety, and problem-solving capacity.", "All state law enforcement agencies shall review policies, training, and practices to confirm alignment with this Executive Order and applicable constitutional standards."], "effective_date": "2026-02-04", "source_type": "executive order"}', '2026-05-20T19:53:14+00:00', 'EXECUTIVE ORDER 12 (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (17, '9 (2026)', 'Executive Order: Equal Opportunity', '2026-01-17', 'Abigail D. Spanberger', 'Virginia', 'This Executive Order establishes a firm policy for the Commonwealth of Virginia to ensure equal opportunity across all state government operations. It explicitly prohibits discrimination based on race, sex, color, national origin, religion, sexual orientation, gender identity or expression, age, political affiliation, disability, and mandates non-discrimination against veterans. The order directs affirmative recruitment measures, outlines a process for addressing violations, and requires annual reviews of state policies to ensure compliance with its non-discrimination directives.', '["Equal Opportunity", "Non-Discrimination", "Employment", "Recruitment", "Public Services", "Veteran Affairs", "Disability Rights", "Diversity and Inclusion"]', '["Office of the Governor", "Department of Human Resource Management", "Office of Equal Employment Services", "Secretary of Administration"]', '["State appointing authorities and management principals are directed to take affirmative measures to emphasize the recruitment of qualified minorities, women, disabled persons, and older Virginians to serve at all levels of state government.", "Allegations of violations of this policy shall be brought to the attention of the Office of Equal Employment Services of the Department of Human Resource Management.", "No state appointing authority, other management principal, or supervisor shall take retaliatory actions against persons making allegations.", "Any state employee found in violation shall be subject to appropriate disciplinary action.", "The Secretary of Administration is directed to review and update annually state procurement, employment, and other relevant policies to ensure compliance with the non-discrimination mandate and report findings to the Governor.", "The Director of the Department of Human Resource Management shall assist the Secretary of Administration in the annual policy review.", "The Department of Human Resource Management is directed to promulgate, review, and update appropriate policies in the Commonwealth''s Standards of Conduct to implement these requirements."]', '2026-01-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/eo/EO-9-EQUAL-OPPORTUNITY.pdf', '{"title": "Executive Order: Equal Opportunity", "order_number": "9 (2026)", "signed_date": "2026-01-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Order establishes a firm policy for the Commonwealth of Virginia to ensure equal opportunity across all state government operations. It explicitly prohibits discrimination based on race, sex, color, national origin, religion, sexual orientation, gender identity or expression, age, political affiliation, disability, and mandates non-discrimination against veterans. The order directs affirmative recruitment measures, outlines a process for addressing violations, and requires annual reviews of state policies to ensure compliance with its non-discrimination directives.", "policy_topics": ["Equal Opportunity", "Non-Discrimination", "Employment", "Recruitment", "Public Services", "Veteran Affairs", "Disability Rights", "Diversity and Inclusion"], "agencies": ["Office of the Governor", "Department of Human Resource Management", "Office of Equal Employment Services", "Secretary of Administration"], "actions_required": ["State appointing authorities and management principals are directed to take affirmative measures to emphasize the recruitment of qualified minorities, women, disabled persons, and older Virginians to serve at all levels of state government.", "Allegations of violations of this policy shall be brought to the attention of the Office of Equal Employment Services of the Department of Human Resource Management.", "No state appointing authority, other management principal, or supervisor shall take retaliatory actions against persons making allegations.", "Any state employee found in violation shall be subject to appropriate disciplinary action.", "The Secretary of Administration is directed to review and update annually state procurement, employment, and other relevant policies to ensure compliance with the non-discrimination mandate and report findings to the Governor.", "The Director of the Department of Human Resource Management shall assist the Secretary of Administration in the annual policy review.", "The Department of Human Resource Management is directed to promulgate, review, and update appropriate policies in the Commonwealth''s Standards of Conduct to implement these requirements."], "effective_date": "2026-01-17", "source_type": "executive order"}', '2026-05-20T19:53:19+00:00', 'NUMBER NINE (2026) 
INSERT INTO governor_executive_orders (id, order_number, title, signed_date, governor, jurisdiction, summary, policy_topics, agencies, actions_required, effective_date, source_type, source_url, raw_json, fetched_at, full_text) VALUES (18, '2', 'Directing the Secretary of Agriculture & Forestry to Establish the Virginia Wood Council', '2026-04-17', 'Abigail D. Spanberger', 'Virginia', 'This Executive Directive establishes the Virginia Wood Council to address economic risks and market challenges facing Virginia''s vital forestry industry, which generates over $21 billion annually. The Council, chaired by the Secretary of Agriculture & Forestry, will serve as a strategic advisory body to align key stakeholders and develop solutions. Its mission includes supporting wood-based businesses, enhancing market development, strengthening supply chain infrastructure, and fostering workforce development to ensure the industry''s continued economic contribution and sustainable resource management. The Council is required to submit an annual report on its progress to the Governor''s Office.', '["Forestry", "Economic Development", "Trade Policy", "Workforce Development", "Natural Resources", "Supply Chain Management"]', '["Secretary of Agriculture & Forestry", "Secretary of Commerce & Trade", "Secretary of Natural & Historic Resources", "Virginia Wood Council", "Department of Agriculture and Consumer Services", "Department of Forestry", "Virginia Economic Development Partnership", "Virginia Department of Conservation and Recreation", "Virginia Farm Bureau", "Virginia Forestry Association", "Virginia Forest Products Association", "Virginia Loggers Association", "Governor''s Office", "Secretary of the Commonwealth"]', '["The Secretary of Agriculture & Forestry, in consultation with the Secretary of Commerce & Trade and the Secretary of Natural & Historic Resources, shall form the Virginia Wood Council.", "The Virginia Wood Council shall support the retention, expansion, and recruitment of wood-based businesses within the Commonwealth.", "The Virginia Wood Council shall provide technical expertise and strategic guidance on domestic and international market development for Virginia-made wood products.", "The Virginia Wood Council shall identify and promote opportunities for investment, innovation, and competitive enhancement in the sector.", "The Virginia Wood Council shall collaborate with public and private partners to ensure Virginia''s forests remain a sustainable resource and an economic driver.", "The Virginia Wood Council shall support workforce development and training programs for wood manufacturing and forest operations.", "The Virginia Wood Council shall recommend policies to strengthen supply chain infrastructure and logistics benefiting forest landowners, wood manufacturers, and timber producers.", "The Virginia Wood Council shall assess the success and further expansion of the Virginia Grown: Forest Products program.", "The Virginia Wood Council shall meet no fewer than three times annually.", "The Virginia Wood Council shall submit an annual report to the Governor''s Office detailing progress toward its goals and objectives by November 1, 2026, and each subsequent year."]', '2026-04-17', 'executive order', 'https://www.governor.virginia.gov/media/governorvirginiagov/governor-of-virginia/pdf/ed/ED-2-Directing-the-Secretary-of-Agriculture--Forestry-to-Establish-the-Virginia-Wood-Council.pdf', '{"title": "Directing the Secretary of Agriculture & Forestry to Establish the Virginia Wood Council", "order_number": "2", "signed_date": "2026-04-17", "governor": "Abigail D. Spanberger", "jurisdiction": "Virginia", "summary": "This Executive Directive establishes the Virginia Wood Council to address economic risks and market challenges facing Virginia''s vital forestry industry, which generates over $21 billion annually. The Council, chaired by the Secretary of Agriculture & Forestry, will serve as a strategic advisory body to align key stakeholders and develop solutions. Its mission includes supporting wood-based businesses, enhancing market development, strengthening supply chain infrastructure, and fostering workforce development to ensure the industry''s continued economic contribution and sustainable resource management. The Council is required to submit an annual report on its progress to the Governor''s Office.", "policy_topics": ["Forestry", "Economic Development", "Trade Policy", "Workforce Development", "Natural Resources", "Supply Chain Management"], "agencies": ["Secretary of Agriculture & Forestry", "Secretary of Commerce & Trade", "Secretary of Natural & Historic Resources", "Virginia Wood Council", "Department of Agriculture and Consumer Services", "Department of Forestry", "Virginia Economic Development Partnership", "Virginia Department of Conservation and Recreation", "Virginia Farm Bureau", "Virginia Forestry Association", "Virginia Forest Products Association", "Virginia Loggers Association", "Governor''s Office", "Secretary of the Commonwealth"], "actions_required": ["The Secretary of Agriculture & Forestry, in consultation with the Secretary of Commerce & Trade and the Secretary of Natural & Historic Resources, shall form the Virginia Wood Council.", "The Virginia Wood Council shall support the retention, expansion, and recruitment of wood-based businesses within the Commonwealth.", "The Virginia Wood Council shall provide technical expertise and strategic guidance on domestic and international market development for Virginia-made wood products.", "The Virginia Wood Council shall identify and promote opportunities for investment, innovation, and competitive enhancement in the sector.", "The Virginia Wood Council shall collaborate with public and private partners to ensure Virginia''s forests remain a sustainable resource and an economic driver.", "The Virginia Wood Council shall support workforce development and training programs for wood manufacturing and forest operations.", "The Virginia Wood Council shall recommend policies to strengthen supply chain infrastructure and logistics benefiting forest landowners, wood manufacturers, and timber producers.", "The Virginia Wood Council shall assess the success and further expansion of the Virginia Grown: Forest Products program.", "The Virginia Wood Council shall meet no fewer than three times annually.", "The Virginia Wood Council shall submit an annual report to the Governor''s Office detailing progress toward its goals and objectives by November 1, 2026, and each subsequent year."], "effective_date": "2026-04-17", "source_type": "executive order"}', '2026-05-20T19:53:25+00:00', 'EXECUTIVE DIRECTIVE 2 (2026) 
