DROP TABLE IF EXISTS governor_actions;
CREATE TABLE governor_actions (
            id             INTEGER PRIMARY KEY AUTOINCREMENT,
            bill_number    TEXT,
            session        TEXT,
            title          TEXT,
            raw_status     TEXT,
            action         TEXT,
            action_key     TEXT,
            action_label   TEXT,
            action_date    TEXT,
            chapter_number TEXT,
            effective_date TEXT,
            governor       TEXT,
            sponsor_name   TEXT,
            sponsor_party  TEXT,
            source_url     TEXT,
            fetched_at     TEXT DEFAULT CURRENT_TIMESTAMP, sponsor_lis_id TEXT,
            UNIQUE(bill_number, session)
        );

-- 2063 governor_actions rows

DROP TABLE IF EXISTS governor_executive_orders;
CREATE TABLE governor_executive_orders (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            order_number    TEXT,
            title           TEXT,
            signed_date     TEXT,
            governor        TEXT,
            jurisdiction    TEXT,
            summary         TEXT,
            policy_topics   TEXT,
            agencies        TEXT,
            actions_required TEXT,
            effective_date  TEXT,
            source_type     TEXT DEFAULT 'executive order',
            source_url      TEXT NOT NULL UNIQUE,
            raw_json        TEXT,
            fetched_at      TEXT NOT NULL
        , full_text TEXT);

